/* Inhouse Cook: all screens share the same persisted plan and shopping state. */
'use strict';
const E=CookEngine,D=COOK_DATA,KEY='inhouse.cook.v2';
const fresh=()=>({version:2,onboarded:false,config:{store:'mercadona',postal:'',people:2,budget:55,days:5,styles:[],diets:[],allergens:[],equipment:['hob','oven']},plan:null,saved:[],favorites:[],history:[],imports:[],pantry:{oliveOil:true,salt:true},extras:[],extraRecipes:{},bought:{},adjustments:{},manual:{},checks:{},servings:{},household:false,cooking:null});
let S=fresh();try{const v=JSON.parse(localStorage.getItem(KEY));if(v?.version===2)S={...S,...v,config:{...S.config,...v.config}};}catch(_){}
let catalogs=[];try{catalogs=JSON.parse(localStorage.getItem(KEY+'.catalogs'))||[];}catch(_){}
const V={screen:S.onboarded?'plan':'wizard',step:0,recipe:null,from:'plan',filter:'all',query:'',busy:false,generation:0,editing:false};
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR'}).format(n||0);
const DAYS=['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'];
const equipment=[['hob','Placa'],['oven','Horno'],['airfryer','Air fryer'],['microwave','Microondas'],['blender','Batidora'],['slowcooker','Olla lenta'],['pressure','Olla a presión'],['kettle','Hervidor']];
const diets=[['vegan','Vegana','Sin ingredientes de origen animal'],['vegetarian','Vegetariana','Sin carne ni pescado'],['pescatarian','Pescetariana','Con pescado, sin carne'],['gluten-free','Sin gluten','Recetas sin ingredientes con gluten'],['dairy-free','Sin lácteos','Sin leche ni derivados']];
const paths={back:'m14 5-7 7 7 7',next:'m9 5 7 7-7 7',plus:'M12 5v14M5 12h14',minus:'M5 12h14',close:'m6 6 12 12M18 6 6 18',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM12 7v5',plan:'M4 5h16v16H4ZM7 2v6M17 2v6M4 10h16M8 14h2M14 14h2M8 18h2',search:'M10.5 18a7.5 7.5 0 1 0 0-15 7.5 7.5 0 0 0 0 15ZM16 16l5 5',basket:'m3 9 3 12h12l3-12H3ZM8 9l4-7 4 7M9 13v4M15 13v4',kitchen:'M3 4h18v17H3ZM3 11h18M13 11v10M6 7h3M15 7h3M6 16h3',star:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z',heart:'M12 21 3 12C-3 3 8-1 12 6c4-7 15-3 9 6Z',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20ZM12 6v6l4 2',refresh:'M20 8a9 9 0 0 0-15-3L2 8M2 2v6h6M4 16a9 9 0 0 0 15 3l3-3M22 22v-6h-6',leaf:'M20 3C6 2 0 10 7 17s15-1 13-14ZM5 20 16 8',cook:'M6 13c-7-2-3-10 2-8 1-5 8-5 9 0 6-2 8 7 1 8v8H6v-8ZM6 17h12',share:'M12 16V2m-5 5 5-5 5 5M4 12v9h16v-9',save:'M5 3h14v19l-7-5-7 5V3Z',check:'m4 12 5 5L20 6',edit:'m4 17-1 4 4-1L21 6l-3-3L4 17ZM14 7l3 3',trash:'M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7M14 10v7',download:'M12 2v14m-5-5 5 5 5-5M4 18v4h16v-4',utensils:'M4 2v7c0 3 6 3 6 0V2M7 2v20M18 2c-5 3-5 10 0 10V2Zm0 10v10'};
const icon=(name,size=20,filled=false)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" aria-hidden="true" fill="${filled?'currentColor':'none'}" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name]||paths.leaf}"/></svg>`;
const action=(a,label,cls='',attrs='')=>`<button type="button" class="${cls}" data-action="${a}" ${attrs}>${label}</button>`;
const ib=(a,i,label,attrs='')=>action(a,icon(i),'icon-btn',`aria-label="${esc(label)}" ${attrs}`);
function persist(){localStorage.setItem(KEY,JSON.stringify(S));}
function recipes(){return [...D.recipes,...S.imports];}
function recipe(id){return recipes().find(r=>r.id===id);}
function catalog(){return catalogs.find(c=>c.store===S.config.store&&c.postal===S.config.postal)||CATALOG_SEED.find(c=>c.store===S.config.store&&c.postal===S.config.postal)||CATALOG_SEED.find(c=>c.store===S.config.store);}
function manual(){return S.manual[S.config.store+'|'+S.config.postal]||{};}
function productMap(){return E.products(catalog(),manual());}
function extraItems(){const meals=Object.entries(S.extraRecipes||{}).map(([recipeId,servings])=>({recipeId,servings}));return [...S.extras,...Object.values(E.amounts(meals,recipes()))];}
function rows(){return E.basket(S.plan?.meals||[],recipes(),productMap(),S.pantry,extraItems(),S.adjustments);}
function counts(){const rr=rows();return{rows:rr,total:E.totals(rr),bought:rr.filter(r=>S.bought[r.key]).length};}
const serving=r=>S.servings[r.id]||S.plan?.meals.find(m=>m.recipeId===r.id)?.servings||S.config.people;
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',3000);}
function sheet(title,body){modal.innerHTML=`<div class="sheet"><div class="sheet-head"><h2>${esc(title)}</h2>${ib('close','close','Cerrar')}</div>${body}</div>`;modal.hidden=false;document.body.style.overflow='hidden';}
function close(){modal.hidden=true;modal.innerHTML='';document.body.style.overflow='';}
function header(){return `<header class="top"><div class="logo">inhouse <span>cook</span></div>${action('location',icon('pin',14)+esc(S.config.postal||'Ubicación'),'location',`aria-label="Cambiar ubicación"`)}</header>`;}
function nav(){return `<nav class="nav" aria-label="Navegación">${[['plan','plan','Mi semana'],['discover','search','Recetas'],['groceries','basket','Compra'],['settings','kitchen','Tu cocina']].map(([a,i,l])=>action('nav',icon(i)+l,V.screen===a?'active':'',`data-screen="${a}"`)).join('')}</nav>`;}
function sourceNote(){const c=catalog();if(!c)return '';const exact=c.postal===S.config.postal,when=new Date(c.updatedAt).toLocaleDateString('es-ES');return `<div class="source-note"><span>${esc(D.stores.find(x=>x.id===c.store)?.name||c.store)} · ${exact?esc(c.postal):'Referencia '+esc(c.postal)} · ${esc(when)}${!exact?' · pendiente de consultar tu zona':''}</span>${action('refresh-prices','Actualizar')}</div>`;}
function render(){close();const functions={wizard:wizard,plan:plan,discover:discover,groceries:groceries,settings:settings,detail:detail,cook:cook,loading:loading};app.innerHTML=(functions[V.screen]||plan)();if(!['wizard','detail','cook','loading'].includes(V.screen))app.insertAdjacentHTML('beforeend',nav());}
function goto(screen){V.screen=screen;render();window.scrollTo(0,0);}
function toggle(arr,value){const i=arr.indexOf(value);if(i>=0)arr.splice(i,1);else arr.push(value);}
function kitchen(){const points=[[17,66],[68,68],[70,39],[6,37],[44,38],[27,17],[50,17],[73,17]];return `<div class="kitchen"><svg class="room" viewBox="0 0 360 265" xmlns="http://www.w3.org/2000/svg"><path fill="#dedacb" d="M0 0h360v175H0z"/><path fill="#d4cbbb" d="m0 175 360 0v90H0z"/><path fill="#f7f6ee" d="M15 105h330v22H15zM20 132h320v104H20z"/><path fill="#b8beaa" d="M22 133h97v103H22zM243 133h97v103h-97z"/><path fill="#384238" d="M130 145h100v78H130z"/><path fill="#959988" d="M143 160h73v46h-73z"/><path fill="#f5f5f0" d="M20 10h105v60H20zM239 10h101v60H239z"/><path stroke="#adad9a" fill="none" d="M71 10v60M290 10v60M39 155h60M39 193h60M262 155h60M262 193h60"/><path fill="#5f6a50" d="M160 106h43v-25h-43zM27 102h43V83H27z"/><path fill="#d5d6c4" d="M280 80h48v27h-48z"/><path stroke="#555e4d" fill="none" stroke-width="4" d="M91 107V89c0-14 22-14 22 0M159 118h43"/></svg>${equipment.map(([id,name],i)=>action('equipment',`${S.config.equipment.includes(id)?'✓ ':''}${name}`,'marker '+(S.config.equipment.includes(id)?'selected':''),`data-id="${id}" style="left:${points[i][0]}%;top:${points[i][1]}%"`)).join('')}</div>`;}
function wizard(){const c=S.config;let title='',sub='',body='';switch(V.step){case 0:title='Tu súper, cerca.';sub='Productos reales. Precios de tu zona.';body=`<div class="stores">${D.stores.map(s=>action('store',`<span class="store-name" style="color:${s.color}">${esc(s.name)}</span><small>Catálogo por código postal</small>${c.store===s.id?'<span class="check-dot">✓</span>':''}`,'store '+(c.store===s.id?'selected':''),`data-id="${s.id}"`)).join('')}</div><div class="field"><label for="postal">Código postal</label><input id="postal" inputmode="numeric" maxlength="5" type="text" autocomplete="postal-code" value="${esc(c.postal)}" placeholder="28001"><p class="hint">Consulta el catálogo online disponible en esa zona.</p></div>${action('geolocate',icon('pin',16)+' Usar mi ubicación','secondary row')}`;break;case 1:title='¿Cuántos a la mesa?';sub='Ajustamos las cantidades y la cesta.';body=`<div class="plate"><div class="plate-circle">${icon('utensils',80)}</div></div><div class="counter">${ib('people-minus','minus','Una persona menos')}<strong>${c.people}</strong>${ib('people-plus','plus','Una persona más')}</div><p class="hint" style="text-align:center">${c.people===1?'Una persona':c.people+' personas'}</p>`;break;case 2:title='Una semana a tu medida.';sub='Presupuesto para las comidas de este plan.';body=`<div class="budget-number"><span id="budget-label">${c.budget}</span> <small>€</small></div><input type="range" id="budget" min="15" max="200" step="1" value="${c.budget}" aria-label="Presupuesto"><div class="range-labels"><span>15 €</span><span>200 €</span></div><div class="section"><p class="eyebrow">Comidas por semana</p><div class="segment">${[3,5,7].map(n=>action('days',n+' días',c.days===n?'active':'',`data-n="${n}"`)).join('')}</div></div><div class="section">${action('pantry',icon('kitchen',17)+' Ya tengo en casa','secondary row')}<p class="hint">La compra cuenta paquetes completos y descuenta tu despensa.</p></div>`;break;case 3:title='¿Qué te apetece?';sub='Elige tus estilos. Puedes combinar varios.';body=`<div class="style-grid">${D.styles.map(t=>action('style',`<img src="${esc(t.image)}" alt=""><span class="label">${esc(t.name)}</span>${c.styles.includes(t.id)?'<span class="check-dot">✓</span>':''}`,'style-tile '+(c.styles.includes(t.id)?'selected':''),`data-id="${t.id}"`)).join('')}</div>`;break;case 4:title='A tu manera.';sub='Tus preferencias, presentes en cada receta.';body=diets.map(([id,n,desc])=>action('diet',icon('leaf',22)+`<span>${n}<small>${desc}</small></span>${c.diets.includes(id)?'<span class="check-dot">✓</span>':''}`,'diet '+(c.diets.includes(id)?'selected':''),`data-id="${id}"`)).join('')+`<div class="section"><p class="eyebrow">Excluir también</p><div class="pills">${[['egg','Huevo'],['fish','Pescado'],['soy','Soja']].map(([a,n])=>action('allergen',n,'pill '+(c.allergens.includes(a)?'active':''),`data-id="${a}"`)).join('')}</div><p class="hint">Comprueba el etiquetado para alergias y trazas.</p></div>`;break;case 5:title='Tu cocina, lista.';sub='Toca los utensilios que tienes.';body=kitchen()+`<div class="pills">${equipment.map(([id,name])=>action('equipment',name,'pill '+(c.equipment.includes(id)?'active':''),`data-id="${id}"`)).join('')}</div><p class="hint">También incluimos recetas sin cocción.</p>`;break;}
return `<header class="top">${ib('wizard-back','back','Volver')}<div class="logo">inhouse <span>cook</span></div>${V.editing?action('cancel-edit','Cerrar','text-btn'):'<span style="width:40px"></span>'}</header><main class="wizard"><div class="progress">${[0,1,2,3,4,5].map(n=>`<i class="${n<=V.step?'past':''}"></i>`).join('')}<span>${V.step+1}/6</span></div><h1>${title}</h1><p class="lede">${sub}</p>${body}</main><div class="sticky-bottom">${action(V.step===5?'generate':'wizard-next',(V.step===5?'Crear mi semana':'Continuar')+icon('next',17),'primary')}</div>`;}
function mealCard(m){const r=recipe(m.recipeId);if(!r)return '';const pc=E.consumptionCost(r,m.servings,productMap(),S.pantry);return `<div class="day">${DAYS[m.day]}</div><article class="meal ${m.done?'done':''}"><button data-action="recipe" data-id="${esc(r.id)}" aria-label="${esc(r.name)}"><img class="meal-photo" src="${esc(r.image)}" alt=""></button><button class="meal-body" data-action="recipe" data-id="${esc(r.id)}"><h3>${esc(r.name)}</h3><div class="meta">${icon('clock',12)} ${r.time} min <span>· ${m.servings} personas</span></div><div class="price">${money(pc.cost/m.servings)} / ración${pc.missing?' + sin precio':''}</div></button>${ib('swap','refresh','Cambiar receta',`data-day="${m.day}"`)}</article>`;}
function plan(){if(!S.plan)return header()+`<main class="page"><p class="eyebrow">Tu semana</p><h1>Comer bien.<br>Sin darle vueltas.</h1><div class="empty">${icon('plan',45)}<p>Elige tu presupuesto y deja lista la semana.</p>${action('edit-config','Crear mi semana','primary')}</div></main>`;const {rows:rr,total,bought}=counts();return header()+`<main class="page"><div class="row between"><div><p class="eyebrow">${S.config.people} personas · ${S.plan.meals.length} comidas</p><h1>Tu semana, resuelta.</h1></div>${ib('edit-config','edit','Editar preferencias')}</div><div class="budget-card"><div><p class="label">Cesta completa</p><strong>${money(total.cost)}</strong><small>de ${money(S.config.budget)}${total.missing?' + '+total.missing+' sin precio':''}</small><div class="progress-bar ${total.cost>S.config.budget?'over':''}"><i style="width:${Math.min(100,total.cost/S.config.budget*100)}%"></i></div></div><div class="divider"></div><button data-action="nav" data-screen="groceries" style="text-align:left;padding:0"><p class="label">Lista de compra</p><strong>${bought}<span style="font-size:15px;color:var(--muted)"> / ${rr.length}</span></strong><small>productos comprados</small><div class="progress-bar"><i style="width:${rr.length?bought/rr.length*100:0}%"></i></div></button></div>${sourceNote()}${total.missing?'<p class="alert">Faltan precios. Añádelos en Compra para conocer el total completo.</p>':''}${total.cost>S.config.budget?'<p class="alert">La cesta supera tu presupuesto. Puedes regenerar o ajustar el plan.</p>':''}${S.plan.shortfall?`<p class="alert">Solo hay ${S.plan.meals.length} recetas distintas compatibles con tus filtros.</p>`:''}<section>${S.plan.meals.map(mealCard).join('')}</section><div class="plan-actions">${action('regenerate',icon('refresh',17)+' Otra semana','secondary row')}${action('save-plan',icon('save',17)+' Guardar','primary')}</div><p class="hint">Una comida principal por día. El coste por ración usa la cantidad consumida; la cesta cuenta los envases que compras.</p></main>`;}
function discover(){let rr=recipes().filter(r=>E.normal(r.name).includes(E.normal(V.query)));if(V.filter==='favorites')rr=rr.filter(r=>S.favorites.includes(r.id));else if(V.filter!=='all')rr=rr.filter(r=>r.tags.includes(V.filter));return header()+`<main class="page"><div class="row between"><div><p class="eyebrow">Tu recetario</p><h1>Algo rico, hoy.</h1></div>${ib('import-recipe','plus','Importar receta')}</div><div class="search">${icon('search',19)}<input id="search" type="search" value="${esc(V.query)}" placeholder="Buscar una receta" aria-label="Buscar recetas"></div><div class="scroll-pills">${[['all','Todas'],['favorites','Guardadas'],...D.styles.map(s=>[s.id,s.name])].map(([id,n])=>action('filter',n,'pill '+(V.filter===id?'active':''),`data-id="${id}"`)).join('')}</div><div class="recipe-grid">${rr.map(r=>`<article class="recipe-card"><button data-action="recipe" data-id="${esc(r.id)}"><img src="${esc(r.image)}" alt="" loading="lazy"><h3>${esc(r.name)}</h3><small>${r.time} min · ${r.baseServings} raciones</small></button>${action('favorite',icon('heart',16,S.favorites.includes(r.id)),'favorite',`data-id="${esc(r.id)}" aria-label="${S.favorites.includes(r.id)?'Quitar de guardadas':'Guardar receta'}" aria-pressed="${S.favorites.includes(r.id)}"`)}</article>`).join('')}</div>${rr.length?'':`<div class="empty"><p>No hay recetas con ese filtro.</p>${action('import-recipe','Añadir receta','secondary')}</div>`}<p class="hint section">Fotos de presentación. Puedes guardar recetas de blogs e importar tus recetas de redes.</p></main>`;}
function detail(){const r=recipe(V.recipe);if(!r){V.screen='discover';return discover();}const n=E.nutrients(r),s=serving(r),pc=E.consumptionCost(r,s,productMap(),S.pantry),checked=S.checks[r.id]||{};return `<div class="cover"><img src="${esc(r.image)}" alt="${esc(r.name)}">${action('back',icon('back'),'icon-btn back','aria-label="Volver"')}${action('favorite',icon('save',20,S.favorites.includes(r.id)),'icon-btn save',`data-id="${esc(r.id)}" aria-label="Guardar receta" aria-pressed="${S.favorites.includes(r.id)}"`)}</div><main class="detail-content"><p class="eyebrow">${esc(r.source.label)}</p><h1>${esc(r.name)}</h1><div class="detail-meta"><span>${r.time} min</span><span>· ${money(pc.cost/s)} / ración${pc.missing?' + sin precio':''}</span></div>${r.source.url?action('open-url','Ver receta original','link',`data-url="${esc(r.source.url)}"`):''}<div class="detail-actions">${action('cook',icon('cook')+' Cocinar')}${action('add-recipe-groceries',icon('basket')+' Compra')}${action('recipe-plan',icon('plan')+' Plan')}</div><div class="nutrition">${[[n.calories,'kcal'],[n.protein+' g','proteínas'],[n.carbs+' g','carbohidratos'],[n.fat+' g','grasas']].map(([v,l])=>`<div><strong>${v}</strong><small>${l}</small></div>`).join('')}</div><p class="hint">Estimación por ración${r.ingredients.some(i=>!D.nutrition[i.key])?' · algunos ingredientes sin datos nutricionales':''}.</p><section class="section"><div class="section-title"><h2>Ingredientes</h2><div class="counter small">${ib('servings-minus','minus','Una ración menos')}<strong>${s}</strong>${ib('servings-plus','plus','Una ración más')}</div></div><div class="row between"><small>${s} ${s===1?'ración':'raciones'}</small>${action('units',S.household?'Ver gramos':'Convertir medidas','link')}</div>${r.ingredients.map(i=>`<div class="ingredient ${checked[i.key]?'checked':''}">${action('ingredient-check','','checkbox '+(checked[i.key]?'checked':''),`data-key="${esc(i.key)}" aria-label="Marcar ${esc(i.label||E.def(i.key).label)}" aria-pressed="${!!checked[i.key]}"`)}<span class="ingredient-name">${esc(i.label||E.def(i.key).label)}</span><span class="amount">${esc(E.formatAmount(i.key,i.amount*s/r.baseServings,S.household,i.unit))}</span></div>`).join('')}${S.household?'<p class="hint">Las tazas y cucharadas son medidas aproximadas.</p>':''}</section><section class="section"><h2>Preparación</h2>${r.steps.map((st,i)=>`<div class="step-row"><span class="step-number">${i+1}</span><p>${esc(st.text)}</p></div>`).join('')}</section><div class="section">${action('cook',icon('cook',18)+' Empezar a cocinar','primary')}</div></main>`;}
function groceries(){
 const {rows:rr,total,bought}=counts();let category='';
 const content=rr.map(row=>{
  const heading=category!==row.category?`<h2 class="grocery-category">${esc(row.category)}</h2>`:'';
  category=row.category;const p=row.product;
  const quantity=p?`<div class="quantity">${action('packs-minus','−','',`data-key="${esc(row.key)}" aria-label="Un envase menos"`)}<span>${row.packs} × ${esc(E.formatAmount(row.key,p.quantity,false,p.unit))}</span>${action('packs-plus','+','',`data-key="${esc(row.key)}" aria-label="Un envase más"`)}</div>`:'';
  const photo=p?.image?`<img src="${esc(p.image)}" alt="" loading="lazy">`:'';
  const productLink=p?.url?action('open-url','Ver producto','link',`data-url="${esc(p.url)}"`):'';
  return heading+`<article class="grocery ${S.bought[row.key]?'bought':''}">${action('bought','','checkbox '+(S.bought[row.key]?'checked':''),`data-key="${esc(row.key)}" aria-label="Comprado: ${esc(row.label)}" aria-pressed="${!!S.bought[row.key]}"`)}${photo}<div class="grocery-body"><h3>${esc(p?.name||row.label)}</h3><small>Necesitas ${esc(E.formatAmount(row.key,row.amount,false,row.unit))}${p?.manual?' · precio añadido por ti':''}${p?.drained?' · peso escurrido':''}${p?.approximateWeight?' · peso aprox.':''}</small>${quantity}<footer>${productLink}${action('edit-price',p?'Editar precio':'Añadir precio','link',`data-key="${esc(row.key)}"`)}${action('have-item','Ya lo tengo','text-btn',`data-key="${esc(row.key)}"`)}</footer></div><span class="cost">${row.cost==null?'—':money(row.cost)}</span></article>`;
 }).join('');
 const empty=`<div class="empty">${icon('basket',45)}<h2>Todo listo.</h2><p>Tu plan y los ingredientes que añadas aparecen aquí.</p>${action('nav','Elegir recetas','secondary','data-screen="discover"')}</div>`;
 return header()+`<main class="page"><div class="row between"><div><p class="eyebrow">${bought} de ${rr.length} comprados</p><h1>La compra, fácil.</h1></div>${ib('share-groceries','share','Compartir lista')}</div><div class="section-title section"><div class="pills">${action('pantry','Despensa','pill')}${action('add-item','Añadir','pill')}${action('reset-bought','Desmarcar','pill')}</div></div>${sourceNote()}${rr.length?content:empty}<div class="grand-total"><span>${total.missing?'Total conocido':'Total de la cesta'}</span><strong>${money(total.cost)}</strong></div>${total.missing?`<p class="alert">${total.missing} ingredientes sin precio. El total completo aún no está disponible.</p>`:''}<p class="hint">Precios del catálogo online y envases completos. Sin gastos de entrega. La disponibilidad y el precio pueden cambiar al comprar.</p></main>`;
}
function settings(){return header()+`<main class="page"><p class="eyebrow">Un sitio para lo tuyo</p><h1>Tu cocina.</h1><section class="section">${[['edit-config','utensils','Preferencias',S.config.people+' personas · '+S.config.days+' comidas'],['location','pin','Súper y ubicación',D.stores.find(s=>s.id===S.config.store)?.name+' · '+S.config.postal],['pantry','kitchen','Mi despensa',Object.values(S.pantry).filter(Boolean).length+' ingredientes'],['show-favorites','heart','Recetas guardadas',S.favorites.length],['import-recipe','plus','Importar receta','Blog, texto o enlace'],['history','clock','Lo que has cocinado',S.history.length],['export','download','Exportar mi cocina','Archivo JSON'],['import-file','download','Importar copia','Archivo JSON'],['about','leaf','Acerca de','Fuentes y créditos']].map(([a,i,l,sub])=>action(a,`<span>${icon(i,20)}<div>${l}<small style="display:block;margin-top:3px">${esc(sub)}</small></div></span>${icon('next',15)}`,'settings-item')).join('')}</section><section class="section"><div class="section-title"><h2>Semanas guardadas</h2><small>${S.saved.length}</small></div>${S.saved.length?S.saved.map(p=>`<article class="saved-plan">${action('load-plan',`<h3>${esc(p.name)}</h3><small>${p.plan.meals.length} comidas · ${new Date(p.date).toLocaleDateString('es-ES')}</small>`,'',`data-id="${esc(p.id)}"`)}${ib('delete-plan','trash','Eliminar semana',`data-id="${esc(p.id)}"`)}</article>`).join(''):'<p class="hint">Guarda una semana para volver a ella.</p>'}</section><section class="section">${action('reset','Borrar mis datos de este dispositivo','text-btn')}</section><p class="footer-version">inhouse cook · 2.0<br>Hecho para cocinar en casa.</p></main>`;}
function loading(){return header()+`<main class="loading"><div class="loading-grid">${['salad','pasta','chicken','rice'].map(i=>`<img src="images/${i}.jpg" alt="">`).join('')}</div><div class="spinner"></div><h1>Una semana que encaja.</h1><p id="loading-message">Consultando productos de tu zona…</p><p class="hint section">Cantidades, utensilios y presupuesto.</p>${action('cancel-generation','Cancelar','text-btn')}</main>`;}
function cook(){const c=S.cooking,r=recipe(c?.recipeId);if(!c||!r){V.screen='plan';return plan();}const st=r.steps[c.step];const seconds=Math.max(0,Math.ceil((c.endsAt-Date.now())/1000));return `<main class="cook"><div class="row between">${ib('exit-cook','back','Salir de cocina')}<span class="recipe-name">${esc(r.name)}</span>${action('cook-jump','Pasos','link')}</div><img class="cook-photo" src="${esc(r.image)}" alt=""><div class="progress">${r.steps.map((_,i)=>`<i class="${i<=c.step?'past':''}"></i>`).join('')}<span>${c.step+1}/${r.steps.length}</span></div><h1>Paso ${c.step+1}.</h1><p class="cook-text">${esc(st.text)}</p>${st.seconds?`<div class="timer"><div><small>Temporizador</small><strong id="timer-value" style="display:block">${timeString(c.endsAt?seconds:st.seconds)}</strong></div>${action(c.endsAt?'timer-stop':'timer-start',c.endsAt?'Reiniciar':'Iniciar','secondary')}</div>`:''}${c.step===r.steps.length-1?`<div class="done-slider"><label for="done">Desliza para marcar como cocinado →</label><input id="done" type="range" value="0" min="0" max="100" aria-label="Marcar como cocinado"></div>`:''}</main><div class="sticky-bottom"><div class="row">${c.step?action('cook-prev',icon('back'),'secondary','aria-label="Paso anterior"'):''}${action(c.step===r.steps.length-1?'finish-cook':'cook-next',c.step===r.steps.length-1?'Terminar':'Siguiente paso','primary')}</div></div>`;}
const timeString=n=>Math.floor(n/60)+':'+String(n%60).padStart(2,'0');
let requestId=0;const pending=new Map();
function native(action,data={},timeout=100000){return new Promise((resolve,reject)=>{if(!window.Native?.request)return reject(new Error('Disponible en el APK'));const id=String(++requestId),timer=setTimeout(()=>{pending.delete(id);reject(new Error('La consulta ha tardado demasiado. Inténtalo de nuevo.'));},timeout);pending.set(id,{resolve,reject,timer});window.Native.request(id,action,JSON.stringify(data));});}
window.NativeResult=(id,result)=>{const p=pending.get(String(id));if(!p)return;clearTimeout(p.timer);pending.delete(String(id));result.ok?p.resolve(result.data):p.reject(new Error(result.error||'No se ha podido completar la acción'));};
window.NativeProgress=(id,text)=>{if(pending.has(String(id))){const el=document.querySelector('#loading-message');if(el)el.textContent=text;}};
async function refreshCatalog(quiet=false){if(!validPostal(S.config.postal))throw new Error('Escribe un código postal español válido.');if(!window.Native?.request){if(!quiet)toast('En el navegador se muestran precios guardados. El APK consulta tu zona.');return catalog();}const result=await native('catalog',{store:S.config.store,postal:S.config.postal});if(result.postal!==S.config.postal||result.store!==S.config.store||!result.locationVerified||!result.products?.length)throw new Error('El supermercado no ha confirmado productos en tu zona.');catalogs=catalogs.filter(c=>!(c.store===result.store&&c.postal===result.postal));catalogs.unshift(result);catalogs=catalogs.slice(0,8);localStorage.setItem(KEY+'.catalogs',JSON.stringify(catalogs));return result;}
const validPostal=p=>/^\d{5}$/.test(p)&&Number(p.slice(0,2))>=1&&Number(p.slice(0,2))<=52;
async function generate(){if(V.busy)return;V.busy=true;const token=++V.generation,previous=S.plan?.meals||[];goto('loading');let warning='';try{await refreshCatalog(true);}catch(err){warning=err.message;}if(token!==V.generation)return;await new Promise(r=>setTimeout(r,100));const result=E.generate(S.config,recipes(),productMap(),S.pantry,Date.now(),previous);V.busy=false;if(result.error){goto('wizard');toast(result.error);return;}S.plan={id:'plan-'+Date.now(),date:new Date().toISOString(),meals:result.meals,shortfall:result.shortfall};S.onboarded=true;S.adjustments={};S.extras=[];S.extraRecipes={};S.bought={};V.editing=false;persist();goto('plan');if(warning)sheet('Precios guardados',`<p class="lede">${esc(warning)} Se ha preparado el plan con la última referencia disponible. Comprueba el código postal y la fecha de precios antes de comprar.</p>${action('close','Continuar','primary')}`);}
function showLocation(){sheet('Tu súper y tu zona',`<div class="pills">${D.stores.map(s=>action('location-store',s.name,'pill '+(s.id===S.config.store?'active':''),`data-id="${s.id}"`)).join('')}</div><div class="field"><label for="new-postal">Código postal</label><input id="new-postal" type="text" inputmode="numeric" maxlength="5" value="${esc(S.config.postal)}"></div>${action('geolocate',icon('pin',16)+' Usar mi ubicación','secondary row')}${action('apply-location','Actualizar precios','primary')}`);}
function pantrySheet(){sheet('Ya tengo en casa',`<p class="lede">Estos ingredientes se descuentan de la compra y del presupuesto.</p>${Object.entries(D.ingredients).filter(([k,d])=>!d.free).map(([k,d])=>`<div class="pantry-row"><span>${esc(d.label)}</span>${action('pantry-toggle','','checkbox '+(S.pantry[k]?'checked':''),`data-key="${k}" aria-label="Tengo ${esc(d.label)}" aria-pressed="${!!S.pantry[k]}"`)}</div>`).join('')}${action('pantry-done','Listo','primary')}`);}
function showSwap(day){const valid=recipes().filter(r=>E.eligible(r,S.config));sheet('Cambiar '+DAYS[day],valid.map(r=>action('select-swap',`<img src="${esc(r.image)}" class="meal-photo" alt=""><div><h3>${esc(r.name)}</h3><small>${r.time} min</small></div>`,'meal row',`data-day="${day}" data-id="${esc(r.id)}" style="width:100%;text-align:left"`)).join(''));}
function showRecipePlan(){const r=recipe(V.recipe);if(!S.plan){S.plan={id:'plan-'+Date.now(),date:new Date().toISOString(),meals:[],shortfall:0};persist();}sheet('Añadir al plan',DAYS.slice(0,S.config.days).map((day,i)=>action('select-swap',`<span>${day}</span><small>${esc(recipe(S.plan.meals.find(m=>m.day===i)?.recipeId)?.name||'Sin receta')}</small>`,'settings-item',`data-day="${i}" data-id="${esc(r.id)}"`)).join(''));}
function importSheet(prefill={}){sheet('Guardar una receta',`<p class="lede">Importa un blog con datos de receta o pega los ingredientes y pasos de tus redes.</p><div class="field"><label for="recipe-url">Enlace original (opcional)</label><input id="recipe-url" type="url" placeholder="https://…" value="${esc(prefill.url||'')}"></div>${action('fetch-recipe','Leer receta del enlace','secondary')}<div class="field"><label for="recipe-author">Autor (opcional)</label><input id="recipe-author" type="text" value="${esc(prefill.author||'')}" placeholder="@creador o nombre"></div><input id="recipe-image" type="hidden" value="${esc(prefill.image||'')}"><div class="field"><label for="recipe-name">Nombre</label><input id="recipe-name" type="text" value="${esc(prefill.name||'')}"></div><div class="price-inputs"><div class="field"><label for="recipe-servings">Raciones</label><input id="recipe-servings" type="number" min="1" max="20" value="${prefill.servings||2}"></div><div class="field"><label for="recipe-time">Minutos</label><input id="recipe-time" type="number" min="1" max="600" value="${prefill.time||25}"></div></div><div class="field"><label for="recipe-ingredients">Ingredientes, uno por línea</label><textarea id="recipe-ingredients" placeholder="200 g arroz&#10;2 huevos">${esc((prefill.ingredients||[]).join('\n'))}</textarea></div><div class="field"><label for="recipe-steps">Pasos, uno por línea</label><textarea id="recipe-steps">${esc((prefill.steps||[]).join('\n'))}</textarea></div><p class="eyebrow">Utensilios de esta receta</p><div class="pills" id="import-equipment">${equipment.map(([id,n])=>action('import-equipment',n,'pill',`data-id="${id}" aria-pressed="false"`)).join('')}</div><p class="hint">Los ingredientes que no podamos identificar aparecen sin precio hasta que los añadas.</p>${action('save-recipe','Guardar receta','primary')}`);}
function priceSheet(key){const row=rows().find(r=>r.key===key);if(!row)return;const p=row.product;sheet('Precio de '+row.label,`<p class="lede">Precio observado por ti en ${esc(S.config.postal)}. Se usará para calcular tu compra.</p><input id="price-key" type="hidden" value="${esc(key)}"><div class="field"><label for="price-name">Nombre del producto</label><input id="price-name" type="text" value="${esc(p?.name||row.label)}"></div><div class="price-inputs"><div class="field"><label for="price-value">Precio del envase (€)</label><input id="price-value" type="number" min="0.01" step="0.01" value="${p?.price||''}"></div><div class="field"><label for="price-quantity">Cantidad (${esc(row.unit)})</label><input id="price-quantity" type="number" min="0.1" step="0.1" value="${p?.quantity||row.amount}"></div></div>${action('save-price','Usar este precio','primary')}${p?.manual?action('remove-price','Volver al catálogo','text-btn',`data-key="${esc(key)}"`):''}`);}
function copyData(){return{app:'Inhouse Cook',version:2,exportedAt:new Date().toISOString(),state:S};}
async function share(text){try{if(window.Native?.request)await native('share',{text});else if(navigator.share)await navigator.share({title:'Inhouse Cook',text});else{await navigator.clipboard.writeText(text);toast('Lista copiada');}}catch(err){if(err.name!=='AbortError')toast(err.message);}}
function exportData(){const text=JSON.stringify(copyData(),null,2);if(window.Native?.request)native('export',{text,name:'inhouse-cook.json'}).catch(e=>toast(e.message));else{const u=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='inhouse-cook.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);}}
function validateImport(data){if(data.app!=='Inhouse Cook'||data.version!==2||!data.state)throw new Error('No es una copia de Inhouse Cook 2.');const v=data.state,c=v.config;if(!c||!D.stores.some(s=>s.id===c.store)||!validPostal(c.postal)||!Number.isInteger(c.people)||c.people<1||c.people>8||![3,5,7].includes(c.days)||!Number.isFinite(c.budget)||c.budget<15||c.budget>200)throw new Error('La configuración de la copia no es válida.');for(const key of ['styles','diets','allergens','equipment'])if(!Array.isArray(c[key])||c[key].some(x=>typeof x!=='string'))throw new Error('Filtros inválidos.');for(const key of ['saved','favorites','history','imports','extras'])if(!Array.isArray(v[key]))throw new Error('La copia está incompleta.');const all=[...D.recipes,...v.imports];for(const r of v.imports){if(typeof r.id!=='string'||typeof r.name!=='string'||!Number.isFinite(r.baseServings)||r.baseServings<1||!Number.isFinite(r.time)||!Array.isArray(r.ingredients)||r.ingredients.some(i=>typeof i.key!=='string'||!Number.isFinite(i.amount)||i.amount<=0||(!D.ingredients[i.key]&&!i.key.startsWith('custom:')))||!Array.isArray(r.steps)||!r.steps.length||r.steps.some(s=>typeof s.text!=='string')||!Array.isArray(r.equipment)||!Array.isArray(r.tags)||typeof r.source?.label!=='string')throw new Error('Hay una receta inválida en la copia.');}
for(const key of ['pantry','bought','adjustments','manual','checks','servings'])if(!v[key]||typeof v[key]!=='object'||Array.isArray(v[key]))throw new Error('Datos guardados inválidos.');
for(const i of v.extras)if(typeof i.key!=='string'||!Number.isFinite(i.amount)||i.amount<=0||(!D.ingredients[i.key]&&!i.key.startsWith('custom:')))throw new Error('Ingrediente de compra inválido.');
for(const dict of Object.values(v.manual))for(const p of Object.values(dict))if(!p||typeof p.name!=='string'||!Number.isFinite(p.price)||p.price<=0||!Number.isFinite(p.quantity)||p.quantity<=0||!['g','ml','ud'].includes(p.unit))throw new Error('Precio guardado inválido.');
for(const [id,n] of Object.entries(v.extraRecipes||{}))if(!all.some(r=>r.id===id)||!Number.isInteger(n)||n<1||n>12)throw new Error('Receta de compra inválida.');
for(const p of [v.plan,...v.saved.map(s=>s.plan)].filter(Boolean))if(!Array.isArray(p.meals)||p.meals.some(m=>!all.some(r=>r.id===m.recipeId)||!Number.isInteger(m.day)||m.day<0||m.day>6||!Number.isInteger(m.servings)||m.servings<1||m.servings>12))throw new Error('Hay un plan inválido en la copia.');return{...fresh(),...v,config:{...fresh().config,...c},cooking:null};}
async function click(el){const a=el.dataset.action,id=el.dataset.id,key=el.dataset.key,n=Number(el.dataset.n);switch(a){
case 'close':close();break;case 'nav':goto(el.dataset.screen);break;case 'back':goto(V.from);break;
case 'wizard-next':if(V.step===0){S.config.postal=document.querySelector('#postal').value.trim();if(!validPostal(S.config.postal))return toast('Escribe un código postal español de 5 cifras.');}V.step=Math.min(5,V.step+1);persist();render();window.scrollTo(0,0);break;
case 'wizard-back':if(V.step>0){V.step--;render();}else if(S.onboarded){goto('plan');}break;
case 'cancel-edit':goto('plan');break;case 'edit-config':V.step=0;V.editing=S.onboarded;goto('wizard');break;
case 'store':S.config.store=id;persist();render();break;case 'people-minus':case 'people-plus':S.config.people=Math.max(1,Math.min(8,S.config.people+(a==='people-plus'?1:-1)));persist();render();break;
case 'days':S.config.days=n;persist();render();break;
case 'style':case 'diet':case 'equipment':case 'allergen':toggle(S.config[{style:'styles',diet:'diets',equipment:'equipment',allergen:'allergens'}[a]],id);persist();render();break;
case 'generate':case 'regenerate':await generate();break;case 'cancel-generation':V.generation++;V.busy=false;goto(S.plan?'plan':'wizard');break;
case 'recipe':V.recipe=id;V.from=V.screen;goto('detail');break;
case 'favorite':toggle(S.favorites,id);persist();const y=window.scrollY;render();window.scrollTo(0,y);break;
case 'filter':V.filter=id;render();break;case 'show-favorites':V.filter='favorites';V.query='';goto('discover');break;
case 'servings-minus':case 'servings-plus':{const r=recipe(V.recipe);S.servings[r.id]=Math.max(1,Math.min(12,serving(r)+(a==='servings-plus'?1:-1)));S.plan?.meals.filter(m=>m.recipeId===r.id).forEach(m=>m.servings=S.servings[r.id]);S.adjustments={};persist();const y=window.scrollY;render();window.scrollTo(0,y);break;}
case 'units':S.household=!S.household;persist();{const y=window.scrollY;render();window.scrollTo(0,y);}break;
case 'ingredient-check':{const checks=S.checks[V.recipe]||(S.checks[V.recipe]={});checks[key]=!checks[key];persist();el.classList.toggle('checked',checks[key]);el.setAttribute('aria-pressed',checks[key]);el.closest('.ingredient').classList.toggle('checked',checks[key]);break;}
case 'add-recipe-groceries':{const r=recipe(V.recipe),s=serving(r);if(S.plan?.meals.some(m=>m.recipeId===r.id)){toast('Esta receta ya está incluida en la compra del plan');break;}S.extraRecipes||={};S.extraRecipes[r.id]=s;for(const i of r.ingredients){delete S.bought[i.key];delete S.adjustments[i.key];}persist();toast('Ingredientes añadidos a la compra');break;}
case 'recipe-plan':showRecipePlan();break;case 'swap':showSwap(Number(el.dataset.day));break;
case 'select-swap':{const day=Number(el.dataset.day),r=recipe(id),m={day,recipeId:id,servings:V.screen==='detail'?serving(r):S.config.people};S.plan.meals=S.plan.meals.filter(x=>x.day!==day);S.plan.meals.push(m);if(S.extraRecipes)delete S.extraRecipes[id];S.plan.meals.sort((a,b)=>a.day-b.day);S.plan.shortfall=0;S.adjustments={};persist();close();goto('plan');break;}
case 'save-plan':sheet('Guardar esta semana',`<div class="field"><label for="plan-name">Nombre</label><input id="plan-name" type="text" maxlength="60" value="Semana del ${new Date().toLocaleDateString('es-ES')}"></div>${action('confirm-save-plan','Guardar','primary')}`);break;
case 'confirm-save-plan':S.saved.unshift({id:'saved-'+Date.now(),name:document.querySelector('#plan-name').value.trim()||'Mi semana',date:new Date().toISOString(),config:structuredClone(S.config),plan:structuredClone(S.plan),pantry:structuredClone(S.pantry)});persist();close();toast('Semana guardada en tu cocina');break;
case 'load-plan':{const p=S.saved.find(p=>p.id===id);S.plan=structuredClone(p.plan);S.config=structuredClone(p.config);S.pantry=structuredClone(p.pantry);S.bought={};S.adjustments={};S.extras=[];S.extraRecipes={};persist();goto('plan');break;}
case 'delete-plan':sheet('Eliminar semana',`<p class="lede">Se eliminará esta semana guardada.</p>${action('confirm-delete-plan','Eliminar','primary',`data-id="${esc(id)}"`)}`);break;
case 'confirm-delete-plan':S.saved=S.saved.filter(p=>p.id!==id);persist();goto('settings');break;
case 'bought':S.bought[key]=!S.bought[key];persist();{const y=window.scrollY;render();window.scrollTo(0,y);}break;
case 'packs-minus':case 'packs-plus':{const row=rows().find(r=>r.key===key);S.adjustments[key]=Math.max(1,row.packs+(a==='packs-plus'?1:-1));persist();const y=window.scrollY;render();window.scrollTo(0,y);break;}
case 'have-item':S.pantry[key]=true;persist();render();break;
case 'reset-bought':S.bought={};persist();render();break;
case 'pantry':pantrySheet();break;case 'pantry-toggle':S.pantry[key]=!S.pantry[key];persist();el.classList.toggle('checked',S.pantry[key]);el.setAttribute('aria-pressed',S.pantry[key]);break;case 'pantry-done':render();break;
case 'add-item':sheet('Añadir a la compra',`<div class="field"><label for="extra-item">Ingrediente y cantidad</label><input id="extra-item" type="text" placeholder="500 g arroz"></div>${action('confirm-item','Añadir','primary')}`);break;
case 'confirm-item':{const text=document.querySelector('#extra-item').value.trim();if(!text)return toast('Escribe un ingrediente.');const i=E.parseIngredient(text);if(i.amount<=0)return toast('La cantidad debe ser mayor que cero.');S.extras.push(i);S.pantry[i.key]=false;persist();close();render();break;}
case 'edit-price':priceSheet(key);break;
case 'save-price':{const key=document.querySelector('#price-key').value,row=rows().find(r=>r.key===key),price=Number(document.querySelector('#price-value').value),quantity=Number(document.querySelector('#price-quantity').value),name=document.querySelector('#price-name').value.trim();if(!name||price<=0||!Number.isFinite(price)||quantity<=0||!Number.isFinite(quantity))return toast('Revisa el precio y la cantidad del envase.');const mk=S.config.store+'|'+S.config.postal;S.manual[mk]||={};S.manual[mk][key]={id:'manual-'+key,name,price,quantity,unit:row.unit,store:S.config.store,manual:true,updatedAt:new Date().toISOString()};delete S.adjustments[key];persist();close();render();break;}
case 'remove-price':delete S.manual[S.config.store+'|'+S.config.postal][key];persist();render();break;
case 'location':showLocation();break;case 'location-store':S.config.store=id;persist();showLocation();break;
case 'apply-location':{const postal=document.querySelector('#new-postal').value.trim();if(!validPostal(postal))return toast('Código postal no válido.');S.config.postal=postal;S.adjustments={};persist();el.disabled=true;el.textContent='Consultando…';try{await refreshCatalog();close();render();}catch(err){close();render();toast(err.message);}break;}
case 'refresh-prices':el.disabled=true;el.textContent='Consultando…';try{await refreshCatalog();render();}catch(err){el.disabled=false;el.textContent='Actualizar';toast(err.message);}break;
case 'geolocate':el.disabled=true;try{const r=await native('location');if(!validPostal(r.postal))throw new Error('No se pudo obtener el código postal. Escríbelo manualmente.');S.config.postal=r.postal;persist();const input=document.querySelector('#postal')||document.querySelector('#new-postal');if(input)input.value=r.postal;toast(r.city||r.postal);}catch(err){toast(err.message);}finally{el.disabled=false;}break;
case 'open-url':if(!/^https:\/\//i.test(el.dataset.url))return;try{if(window.Native?.request)await native('open',{url:el.dataset.url});else window.open(el.dataset.url,'_blank','noopener');}catch(e){toast(e.message);}break;
case 'share-groceries':await share('Inhouse Cook · '+S.config.postal+'\n\n'+rows().map(r=>(S.bought[r.key]?'✓ ':'□ ')+(r.product?.name||r.label)+' · '+(r.packs?r.packs+' envase(s)':E.formatAmount(r.key,r.amount,false,r.unit))+' · '+(r.cost==null?'sin precio':money(r.cost))).join('\n')+'\n\nTotal conocido: '+money(counts().total.cost));break;
case 'import-recipe':importSheet();break;case 'import-equipment':el.classList.toggle('active');el.setAttribute('aria-pressed',el.classList.contains('active'));break;
case 'fetch-recipe':{const url=document.querySelector('#recipe-url').value.trim();if(!/^https:\/\//i.test(url))return toast('Pega un enlace HTTPS válido.');el.disabled=true;el.textContent='Leyendo…';try{const r=await native('recipe',{url});importSheet({...r,url});}catch(err){toast(err.message);el.disabled=false;el.textContent='Leer receta del enlace';}break;}
case 'save-recipe':{const name=document.querySelector('#recipe-name').value.trim(),url=document.querySelector('#recipe-url').value.trim(),lines=document.querySelector('#recipe-ingredients').value.split('\n').map(x=>x.trim()).filter(Boolean),steps=document.querySelector('#recipe-steps').value.split('\n').map(x=>x.trim()).filter(Boolean),servings=Number(document.querySelector('#recipe-servings').value),time=Number(document.querySelector('#recipe-time').value);if(!name||!lines.length||!steps.length||!Number.isInteger(servings)||servings<1||servings>20||!Number.isFinite(time)||time<1||time>600)return toast('Completa nombre, raciones, ingredientes y pasos.');if(url&&!/^https:\/\//i.test(url))return toast('El enlace debe comenzar con https://');const ingredients=lines.map(E.parseIngredient);if(ingredients.some(i=>i.amount<=0))return toast('Revisa las cantidades de los ingredientes.');const id='import-'+Date.now();S.imports.push({id,name,baseServings:servings,time,image:/^https:\/\//i.test(document.querySelector('#recipe-image').value)?document.querySelector('#recipe-image').value:'images/salad.jpg',equipment:[...document.querySelectorAll('#import-equipment .active')].map(e=>e.dataset.id),tags:time<=20?['quick']:[],ingredients,steps:steps.map(text=>({text,seconds:0})),source:{label:document.querySelector('#recipe-author').value.trim()||(url?new URL(url).hostname:'Tu receta'),type:'import',url}});S.favorites.push(id);persist();close();V.recipe=id;V.from='discover';goto('detail');toast('Receta guardada');break;}
case 'export':exportData();break;case 'import-file':document.querySelector('#file-import').click();break;
case 'history':sheet('Lo que has cocinado',S.history.length?S.history.slice().reverse().map(h=>`<div class="saved-plan"><div><h3>${esc(recipe(h.recipeId)?.name||h.name)}</h3><small>${new Date(h.date).toLocaleDateString('es-ES')} · ${h.rating?'★'.repeat(h.rating):'Sin valoración'}</small></div></div>`).join(''):'<p class="lede">Termina una receta en modo cocina y aparecerá aquí.</p>');break;
case 'cook':{const r=recipe(V.recipe);if(S.cooking?.recipeId!==r.id)S.cooking={recipeId:r.id,step:0,servings:serving(r),endsAt:0};persist();native('awake',{enabled:true}).catch(()=>{});goto('cook');break;}
case 'exit-cook':native('awake',{enabled:false}).catch(()=>{});goto('detail');break;
case 'cook-next':case 'cook-prev':S.cooking.step+=a==='cook-next'?1:-1;S.cooking.endsAt=0;persist();render();break;
case 'cook-jump':sheet('Preparación',recipe(S.cooking.recipeId).steps.map((s,i)=>action('select-step',`<span class="step-number">${i+1}</span><span>${esc(s.text)}</span>`,'step-row',`data-n="${i}" style="text-align:left"`)).join(''));break;
case 'select-step':S.cooking.step=n;S.cooking.endsAt=0;persist();render();break;
case 'timer-start':S.cooking.endsAt=Date.now()+recipe(S.cooking.recipeId).steps[S.cooking.step].seconds*1000;persist();render();break;
case 'timer-stop':S.cooking.endsAt=0;persist();render();break;
case 'finish-cook':{const r=recipe(S.cooking.recipeId),entry={id:'cooked-'+Date.now(),recipeId:r.id,name:r.name,date:new Date().toISOString(),servings:S.cooking.servings,rating:0};S.history.push(entry);S.plan?.meals.filter(m=>m.recipeId===r.id).forEach(m=>m.done=true);S.cooking=null;persist();native('awake',{enabled:false}).catch(()=>{});goto('detail');sheet('¿Qué tal ha quedado?',`<p class="lede">${esc(r.name)} · cocinado ✓</p><div class="rating">${[1,2,3,4,5].map(n=>action('rate','★','',`data-id="${entry.id}" data-n="${n}" aria-label="${n} estrellas"`)).join('')}</div>${action('close','Listo','primary')}`);break;}
case 'rate':S.history.find(h=>h.id===id).rating=n;persist();close();toast('Valoración guardada');break;
case 'about':sheet('Inhouse Cook',`<p class="lede">Versión 2.0.0 · Inhouse.</p><div class="section"><h3>Fotografía</h3><p class="hint">Tortilla: Tamorlan, CC BY-SA 3.0. Otras fotos de presentación: Unsplash. Las fotos de productos pertenecen a los catálogos de Mercadona y DIA.</p>${action('open-url','Créditos completos','link','data-url="https://github.com/miguelcoxcaballero/inhouse-cook/blob/main/docs/credits.md"')}</div><div class="section"><h3>Tipografías</h3><p class="hint">Comfortaa, DM Sans y Playfair Display · SIL Open Font License. Licencias incluidas en la aplicación.</p></div><div class="section"><h3>Datos</h3><p class="hint">Precios del catálogo online de cada zona; pueden cambiar al comprar. Nutrición y medidas domésticas estimadas. Comprueba las etiquetas para alergias y trazas.</p></div>`);break;
case 'reset':sheet('Borrar datos',`<p class="lede">Se borrarán tus planes, recetas importadas y preferencias de este dispositivo. Exporta antes una copia si quieres conservarlos.</p>${action('confirm-reset','Borrar datos','primary')}`);break;
case 'confirm-reset':S=fresh();catalogs=[];localStorage.removeItem(KEY+'.catalogs');persist();V.step=0;V.editing=false;goto('wizard');break;
}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled)click(el).catch(err=>{V.busy=false;toast(err.message||'No se pudo completar la acción');});});
document.addEventListener('input',e=>{if(e.target.id==='postal'){S.config.postal=e.target.value;persist();}if(e.target.id==='budget'){S.config.budget=Number(e.target.value);persist();document.querySelector('#budget-label').textContent=S.config.budget;}if(e.target.id==='search'){V.query=e.target.value;const start=e.target.selectionStart;render();const input=document.querySelector('#search');input.focus();try{input.setSelectionRange(start,start);}catch(_){}}if(e.target.id==='done'&&Number(e.target.value)>=95)click({dataset:{action:'finish-cook'}});});
document.querySelector('#file-import').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw new Error('La copia es demasiado grande (máximo 5 MB).');const next=validateImport(JSON.parse(await file.text()));sheet('Restaurar tu cocina',`<p class="lede">La copia contiene ${next.saved.length} semanas y ${next.imports.length} recetas. Sustituirá los datos de este dispositivo.</p>${action('confirm-restore','Restaurar copia','primary')}`);const b=modal.querySelector('[data-action="confirm-restore"]');b.addEventListener('click',()=>{S=next;persist();goto(S.onboarded?'plan':'wizard');toast('Copia restaurada');},{once:true});}catch(err){toast(err.message);}e.target.value='';});
setInterval(()=>{if(V.screen!=='cook'||!S.cooking?.endsAt)return;const seconds=Math.max(0,Math.ceil((S.cooking.endsAt-Date.now())/1000)),el=document.querySelector('#timer-value');if(el)el.textContent=timeString(seconds);if(!seconds){S.cooking.endsAt=0;persist();toast('Tiempo terminado');if(navigator.vibrate)navigator.vibrate([200,100,200]);render();}},1000);
window.App={back(){if(!modal.hidden){close();return true;}if(V.screen==='cook'){native('awake',{enabled:false}).catch(()=>{});goto('detail');return true;}if(V.screen==='detail'){goto(V.from);return true;}if(V.screen==='wizard'&&V.step>0){V.step--;render();return true;}if(V.screen==='loading'){V.generation++;V.busy=false;goto(S.plan?'plan':'wizard');return true;}if(V.screen!=='plan'&&S.onboarded){goto('plan');return true;}return false;}};
render();
